style:
:root {
  --btn-bg: #1e293b;
  --btn-border: #1e293b;
  --btn-color: #bfdbfe;
  --btn-hover-bg: #64748b;
  --btn-hover-border: #e9d5ff;
  --btn-active-bg: #3b82f6;
  --btn-icon-bg: #14b8a6;
  --btn-icon-color: #1e293b;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  height: 30px;
  padding: 0 10px 0 30px;
  border-radius: 14px;
  border: 1px solid var(--btn-border);
  background-color: var(--btn-bg);
  color: var(--btn-color);
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.08);
  cursor: pointer;
  transition: all 200ms ease-in-out;
  &:hover {
    border-color: var(--btn-hover-border);
    background-color: var(--btn-hover-bg);
    .btn-primary__icon {
      width: calc(100% - 4px);
      z-index: 5;
    }
  }
  &:active {
    transform: translateY(1px);
    background-color: var(--btn-active-bg);
  }
}

children.style:
.btn-primary__icon {
  background: var(--btn-icon-bg);
  border-radius: 14px;
  width: 26px;
  height: 26px;
  display: flex;
  position: absolute;
  left: 2px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--btn-icon-color);
  transition: all 0.2s ease;
  padding: 0;
}
